function resolveArchiveInput(cwd, targetArg) {
  assertNonEmptyString(cwd, 'cwd');
  assertNonEmptyString(targetArg, 'targetArg');
  const normalizedCwd = path.resolve(cwd);
  const resolvedPath = path.resolve(normalizedCwd, targetArg);
  const rel = path.relative(normalizedCwd, resolvedPath);
  const isInsideCwd = rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
  return { resolvedPath, isInsideCwd };
}

module.exports = { resolveArchiveInput };

