problems.solutionCode:
const DEFAULT_PORT = 3000;
const DEFAULT_ENV = 'development';
const MIN_PORT = 1;
const MAX_PORT = 65535;

function readFlagValue(argv, index, name) {
  const arg = argv[index];
  const prefix = `${name}=`;
  if (arg.startsWith(prefix)) return { value: arg.slice(prefix.length), nextIndex: index };
  if (arg === name) {
    if (index + 1 >= argv.length) return { error: `Missing value for ${name}` };
    return { value: argv[index + 1], nextIndex: index + 1 };
  }
  return null;
}

function parseCliFlags(argv) {
  const parsed = { port: undefined, appEnv: undefined, error: null };
  for (let i = 0; i < argv.length; i += 1) {
    const portHit = readFlagValue(argv, i, '--port');
    if (portHit) {
      if (portHit.error) return { ...parsed, error: portHit.error };
      parsed.port = portHit.value;
      i = portHit.nextIndex;
      continue;
    }
    const envHit = readFlagValue(argv, i, '--env');
    if (envHit) {
      if (envHit.error) return { ...parsed, error: envHit.error };
      parsed.appEnv = envHit.value;
      i = envHit.nextIndex;
      continue;
    }
    if (argv[i].startsWith('-')) return { ...parsed, error: `Unknown flag: ${argv[i]}` };
  }
  return parsed;
}

function pickSetting(flagVal, envVal, fallback) {
  if (flagVal !== undefined) return flagVal;
  if (envVal !== undefined && envVal !== '') return envVal;
  return fallback;
}

function parseValidPort(rawPort) {
  if (typeof rawPort === 'string' && rawPort.trim() === '') return null;
  const num = Number(rawPort);
  if (!Number.isInteger(num) || num < MIN_PORT || num > MAX_PORT) return null;
  return num;
}

function runPreflight(argv = [], env = {}) {
  const flags = parseCliFlags(argv);
  if (flags.error) {
    return { exitCode: 1, stdout: '', stderr: `Error: ${flags.error}\n` };
  }
  const rawPort = pickSetting(flags.port, env.PORT, DEFAULT_PORT);
  const port = parseValidPort(rawPort);
  if (port === null) {
    return { exitCode: 1, stdout: '', stderr: `Error: Invalid port ${String(rawPort)}\n` };
  }
  const appEnv = pickSetting(flags.appEnv, env.APP_ENV, DEFAULT_ENV);
  return { exitCode: 0, stdout: `${JSON.stringify({ port, env: appEnv })}\n`, stderr: '' };
}

module.exports = { runPreflight };

