const fs = require('node:fs');
const path = require('node:path');

function checkDirs(root) {
  const missing = [];
  for (const dir of ['src', 'tests']) {
    const full = path.join(root, dir);
    if (!fs.existsSync(full) || !fs.statSync(full).isDirectory()) missing.push(dir);
  }
  return missing;
}

function checkManifest(root) {
  const pkgPath = path.join(root, 'package.json');
  if (!fs.existsSync(pkgPath)) return ['Missing package.json'];
  try {
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
    if (typeof pkg.main === 'string') {
      const rel = path.relative(root, path.resolve(root, pkg.main));
      if (path.isAbsolute(pkg.main) || rel.startsWith('..')) {
        return ['package.json main escapes projectRoot'];
      }
    }
    return [];
  } catch (_err) {
    return ['Invalid package.json'];
  }
}

function auditProjectLayout(projectRoot) {
  const root = path.resolve(projectRoot);
  const missingDirs = checkDirs(root);
  const manifestErrors = checkManifest(root);
  const ignoreErrors = [];
  const ignorePath = path.join(root, '.gitignore');
  if (!fs.existsSync(ignorePath)) {
    ignoreErrors.push('Missing .gitignore');
  } else {
    const raw = fs.readFileSync(ignorePath, 'utf8');
    if (!raw.includes('node_modules')) ignoreErrors.push('Missing node_modules/ in .gitignore');
  }
  const ok = missingDirs.length === 0 && manifestErrors.length === 0 && ignoreErrors.length === 0;
  return { ok, missingDirs, manifestErrors, ignoreErrors };
}

module.exports = { auditProjectLayout };

