const fs = require('node:fs');
const path = require('node:path');

function checkDirs(root) {
  const missing = [];
  for (const dir of ['src', 'tests']) {
    const full = path.join(root, dir);
    if (!fs.existsSync(full) || !fs.statSync(full).isDirectory()) missing.push(dir);
  }
  return missing;
}

function checkManifest(root) {
  const pkgPath = path.join(root, 'package.json');
  if (!fs.existsSync(pkgPath)) return ['Missing package.json'];
  try {
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
    if (typeof pkg.main === 'string') {
      const resolvedMain = path.resolve(root, pkg.main);
      const rel = path.relative(root, resolvedMain);
      if (path.isAbsolute(pkg.main) || rel === '..' || rel.startsWith(`..${path.sep}`) || path.isAbsolute(rel)) {
        return ['package.json main must be relative and inside projectRoot'];
      }
    }
    return [];
  } catch (_err) {
    return ['Invalid package.json'];
  }
}

function checkGitignore(root) {
  const ignorePath = path.join(root, '.gitignore');
  if (!fs.existsSync(ignorePath)) return ['Missing .gitignore'];
  const lines = fs
    .readFileSync(ignorePath, 'utf8')
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line !== '' && !line.startsWith('#'));
  const errors = [];
  if (!lines.includes('node_modules') && !lines.includes('node_modules/')) {
    errors.push('Missing node_modules/ in .gitignore');
  }
  if (!lines.includes('.env')) {
    errors.push('Missing .env in .gitignore');
  }
  return errors;
}

function auditProjectLayout(projectRoot) {
  const root = path.resolve(projectRoot);
  const missingDirs = checkDirs(root);
  const manifestErrors = checkManifest(root);
  const ignoreErrors = checkGitignore(root);
  const ok = missingDirs.length === 0 && manifestErrors.length === 0 && ignoreErrors.length === 0;
  return { ok, missingDirs, manifestErrors, ignoreErrors };
}

module.exports = { auditProjectLayout };

