try {
  fs.mkdirSync(path.join(dir, 'src'));
  fs.mkdirSync(path.join(dir, 'tests'));
  fs.writeFileSync(path.join(dir, 'package.json'), JSON.stringify({ name: 'demo', main: './src/index.js' }));
  fs.writeFileSync(path.join(dir, '.gitignore'), 'node_modules/\n.env\n');
  const res = auditProjectLayout(dir);
  assert.deepStrictEqual(res, { ok: true, missingDirs: [], manifestErrors: [], ignoreErrors: [] });
} finally {
  fs.rmSync(dir, { recursive: true, force: true });
}

